dashboard.run(function ($rootScope, $state, AuthService, $cookieStore) {  // 4-11-2016 added run function start
    $rootScope.$on("$stateChangeStart", function (event, toState, toParams, fromState, fromParams) {
        var loginCookie = $cookieStore.get('IsLogged');
        //var sessioncookie = $cookieStore.get('IVRMApplication');

        //if (toState.isFree && sessioncookie == null)
        //{
        //    window.location.href = "https://baldwinvapsecampus.com/#/login/100";
        //}

        $rootScope.inArray = function (item, array) {
            return (-1 !== array.indexOf(item));
        };

        if (toState.isFree && loginCookie !== "true") {
            // reload the login route       
            $state.transitionTo("Login");
            event.preventDefault();
        }
    }); // 4-11-2016  run function end
});

dashboard.directive('allowPattern', function () {
    return {
        restrict: 'A',
        require: '?allowPattern',
        scope: {},
        replace: false,
        link: function (scope, element, attrs) {
            element.bind('keypress', function (event) {
                var regex = new RegExp(attrs.allowPattern);
                var charCode = !event.charCode ? event.which : event.charCode;
                // check for tab & backspace for Firefox:
                if ([0, 8].indexOf(charCode) !== -1) return;
                var key = String.fromCharCode(charCode);
                if (!regex.test(key)) {
                    event.preventDefault();
                    return false;
                }
            });
        }
    };
});


dashboard.factory('Excel', function ($window) {
    var uri = 'data:application/vnd.ms-excel;base64,',
        template = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="https://www.w3.org/TR/REC-html40"><head><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>{worksheet}</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table>{table}</table></body></html>',
        base64 = function (s) { return $window.btoa(unescape(encodeURIComponent(s))); },
        format = function (s, c) { return s.replace(/{(\w+)}/g, function (m, p) { return c[p]; }) };
    return {
        tableToExcel: function (tableId, worksheetName) {
            var table = $(tableId),
                ctx = { worksheet: worksheetName, table: table.html() },
                href = uri + base64(format(template, ctx));
            return href;
        }
    };
});

dashboard.filter('propsFilter', function () {
    return function (items, props) {
        var out = [];
        if (angular.isArray(items)) {
            items.forEach(function (item) {
                var keys = Object.keys(props);
                var prop = keys[0];
                var text = props[prop].toLowerCase();
                if (item[prop].toString().toLowerCase().indexOf(text) === 0) {
                    out.push(item);
                }
            });
        } else {
            out = items;
        }
        return out;
    };
});

dashboard.factory('FormSubmitter', FormSubmitter)
    .directive('formSubmitter', formSubmitterDirective);

function FormSubmitter($rootScope, $sce) {
    // Expose our Api
    return {
        submit: submit
    }


    function submit(url, method, params) {
        url = $sce.trustAsResourceUrl(url);

        $rootScope.$broadcast('form.submit', {
            url: url,
            method: method,
            params: params
        });
    }
}

function formSubmitterDirective($timeout) {
    return {
        restrict: 'E',
        replace: true,
        template:
            '<form action="{{ formData.url }}" method="{{ formData.method }}">' +
            '   <div ng-repeat="(key,val) in formData.params">' +
            '       <input type="hidden" name="{{ key }}" value="{{ val }}" />' +
            '   </div>' +
            '</form>',
        link: function ($scope, $element, $attrs) {
            $scope.$on('form.submit', function (event, data) {
                $scope.formData = data;

                console.log('auto submitting form...');

                $timeout(function () {
                    $element.submit();
                })
            })
        }
    }
}

